AULAS["rKHmZvjEHvc"] = aula_en(
    "Contar o que alguém disse: “Ele disse que estava cansado.” No reported speech, o verbo costuma <b>voltar um tempo</b> (<i>I am → he said he was</i>) e os pronomes mudam conforme quem conta. E perguntas viram afirmativas: <i>She asked if I was ready.</i>",
    ["relatar frases com <i>said (that)</i> e <i>told me</i>;", "fazer o recuo dos tempos verbais;", "relatar perguntas e pedidos."],
    ("Ana disse: “I'm tired.” Relatando:", ["Ana said she is tired.", "Ana said she was tired.", "Ana told she was tired."], 1,
     ["Possível se ainda for verdade, mas o padrão é recuar o tempo.", "Isso! am → was.", "<i>told</i> precisa de quem ouviu: <i>told me</i>."],
     "say (that) / tell + pessoa; tempo recua."),
    ("Recado", [
        ("Bob", "What did the manager say?", "O que o gerente disse?"),
        ("Cida", "She said that the meeting was cancelled.", "Ela disse que a reunião foi cancelada."),
        ("Bob", "Did she tell you why?", "Ela te disse por quê?"),
        ("Cida", "She told me she had a doctor's appointment. She asked if we could meet on Friday.", "Ela me disse que tinha médico. Perguntou se poderíamos nos reunir na sexta."),
        ("Bob", "And she told us to send the report first.", "E pediu para enviarmos o relatório antes."),
    ]),
    "como as frases mudam ao serem relatadas",
    tabela("Recuo dos tempos", ["Direto", "Relatado"], [
        ["“I am tired.”", "He said he was tired."], ["“I work here.”", "She said she worked there."], ["“I will call.”", "He said he would call."],
        ["“I can help.”", "She said she could help."], ["“I saw it.”", "He said he had seen it."], ["“Are you ready?”", "She asked if I was ready."],
        ["“Send the report.”", "He told me to send the report."],
    ], corpo="<p>Mudam também: <i>here → there, today → that day, tomorrow → the next day</i>.</p>"),
    [("He said (that) ...", "Ele disse que ...", "He said he was busy."), ("She told me ...", "Ela me disse ...", "She told me the news."), ("He asked if ...", "Ele perguntou se ...", "He asked if I was OK."),
     ("She told me to ...", "Ela me pediu para ...", "She told me to wait."), ("She asked me to ...", "Ela me pediu para ...", "She asked me to help."), ("appointment", "consulta / compromisso", "I have a doctor's appointment.")],
    [("She said she was busy.", ["Ela disse que estava ocupada", "Ela está ocupada", "Ela disse para eu estar ocupado"], 0, "Ela disse que estava ocupada."),
     ("He asked if I was ready.", ["Ele perguntou se eu estava pronto", "Ele estava pronto", "Ele disse que estava pronto"], 0, "Ele perguntou se eu estava pronto."),
     ("She told me to wait.", ["Ela me pediu para esperar", "Ela esperou por mim", "Ela me disse que esperou"], 0, "Ela me pediu para esperar."),
     ("He said he would call.", "5 palavras"), ("She told me the news.", "5 palavras")],
    [("She said that the meeting was cancelled.", "Ela disse que a reunião foi cancelada."), ("He told me to send the report.", "Ele me pediu para enviar o relatório."), ("She asked if I could help.", "Ela perguntou se eu podia ajudar."), ("He said he would call later.", "Ele disse que ligaria mais tarde.")],
    [("<i>He said me</i>.", "<i>He told me</i> ou <i>He said (to me)</i>."), ("<i>She asked was I ready</i>.", "Ordem de afirmativa: <i>She asked if I was ready</i>."), ("<i>He told to wait</i>.", "<i>tell</i> pede a pessoa: <i>He told <b>me</b> to wait</i>.")],
    "<p>Em resumos de reunião: <b>The client said they needed the feature by May</b>, <b>Ana asked if we could add tests</b>, <b>They told us to prioritize the API</b>.</p>",
    [("Relatando “I will help”:", ["He said he will help.", "He said he would help.", "He told he would help."], 1, "will → would."),
     ("Correto:", ["She said me the truth.", "She told me the truth.", "She told the truth me."], 1, "tell + pessoa."),
     ("Relatando “Are you OK?”:", ["He asked if I was OK.", "He asked was I OK?", "He said are you OK."], 0, "if + ordem normal.")],
    ["say (that) / tell + pessoa.", "Tempos recuam: am → was, will → would, can → could.", "Perguntas: asked if/what...; pedidos: told/asked me to."],
    "Aula 11: três desejos (wish).", "she said that")

